CREATE OR REPLACE FUNCTION public.correct_credit_payment(p_payment_id uuid,p_amount numeric,p_date date,p_method text DEFAULT 'other',p_reference text DEFAULT NULL) RETURNS public.credits LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.credits; p public.credit_payments; new_paid numeric; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Connexion requise'; END IF; SELECT * INTO p FROM public.credit_payments WHERE id=p_payment_id AND user_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Paiement introuvable'; END IF; SELECT * INTO c FROM public.credits WHERE id=p.credit_id AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Crédit introuvable'; END IF; SELECT * INTO p FROM public.credit_payments WHERE id=p_payment_id AND user_id=auth.uid() FOR UPDATE; IF p_amount IS NULL OR p_amount<=0 OR p_date IS NULL OR p_method NOT IN ('other','cash','transfer','cheque','effet') OR length(p_reference)>250 THEN RAISE EXCEPTION 'Paiement invalide'; END IF; new_paid:=COALESCE(c.paid_amount,0)-p.amount+p_amount; IF new_paid<0 OR new_paid>COALESCE(c.amount,c.total_amount,0) THEN RAISE EXCEPTION 'Le paiement dépasse le reste dû'; END IF; UPDATE public.credit_payments SET amount=p_amount,paid_at=p_date,method=p_method,reference=p_reference WHERE id=p.id; UPDATE public.credits SET paid_amount=new_paid,status=CASE WHEN new_paid=COALESCE(c.amount,c.total_amount,0) THEN 'rembourse' WHEN new_paid>0 THEN 'partiel' ELSE 'en_cours' END WHERE id=c.id RETURNING * INTO c; RETURN c; END $$; REVOKE ALL ON FUNCTION public.correct_credit_payment(uuid,numeric,date,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.correct_credit_payment(uuid,numeric,date,text,text) TO authenticated; CREATE TRIGGER credit_payments_corrections_history AFTER UPDATE ON public.credit_payments FOR EACH ROW EXECUTE FUNCTION public.capture_activity_history();